import{_ as t,o,c as r,ag as a}from"./chunks/framework.DNmTgtHf.js";const m=JSON.parse('{"title":"Builder — Overview","description":"","frontmatter":{},"headers":[],"relativePath":"design_patterns/creational/builder/Builder.md","filePath":"design_patterns/creational/builder/Builder.md"}'),i={name:"design_patterns/creational/builder/Builder.md"};function d(s,e,n,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="builder-—-overview" tabindex="-1">Builder — Overview <a class="header-anchor" href="#builder-—-overview" aria-label="Permalink to &quot;Builder — Overview&quot;">​</a></h1><p>The Builder pattern constructs a complex object step-by-step, separating the <em>configuration</em> of a product from its final <em>materialisation</em>. The umbrella thesis: callers should not write <code>new ConcreteProduct(...)</code> directly when the product has many fields, several optional, and is meant to be immutable and validated.</p><p>This package walks four variants, each in its own subpackage. The four are progressively richer, but they share the same product family (<code>JobOffer</code>) so the comparison is concrete.</p><h2 id="the-four-variants" tabindex="-1">The four variants <a class="header-anchor" href="#the-four-variants" aria-label="Permalink to &quot;The four variants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variant</th><th>Subpackage</th><th>Doc</th><th>What&#39;s added on top</th></tr></thead><tbody><tr><td>Hand-written EJ-style Builder</td><td><code>simple_builder/</code></td><td><code>BuilderBasic.md</code></td><td>Required-field enforcement, fluent setters, validation in <code>build()</code>, immutability</td></tr><tr><td>Lombok <code>@Builder</code></td><td><code>lombok_builder/</code></td><td><code>BuilderLombok.md</code></td><td>Annotation generates the boilerplate — at the cost of required-field enforcement and validation</td></tr><tr><td>Director (simple)</td><td><code>director_builder/</code></td><td><code>BuilderDirector.md</code></td><td>Director holds reusable recipes typed against a concrete builder</td></tr><tr><td>Director (GoF)</td><td><code>director_builder_gof/</code></td><td><code>BuilderDirectorGof.md</code></td><td>Director recipes typed against a shared step interface, so the same recipe drives multiple builders producing different artefacts</td></tr></tbody></table><h2 id="when-to-reach-for-which" tabindex="-1">When to reach for which <a class="header-anchor" href="#when-to-reach-for-which" aria-label="Permalink to &quot;When to reach for which&quot;">​</a></h2><ul><li><strong>EJ-style Builder</strong> is the default for &quot;an immutable object with several optional fields, validated at construction.&quot; 90% of real Builder usage.</li><li><strong>Lombok <code>@Builder</code></strong> is the default when the product is simple, the contract is permissive, and the boilerplate cost matters more than required-field enforcement.</li><li><strong>Simple Director</strong> is worth adding when you have N call sites configuring the same multi-step &quot;named template&quot; (standard / senior / relocate). One place owns the recipe.</li><li><strong>GoF Director</strong> is worth adding when <em>more than one product</em> shares a construction recipe and is best built side-by-side. In production code, often replaced by <code>model.build()</code> followed by a separate renderer/serialiser — see <code>BuilderDirectorGof.md</code> for that trade-off.</li></ul><h2 id="what-every-variant-has-in-common" tabindex="-1">What every variant has in common <a class="header-anchor" href="#what-every-variant-has-in-common" aria-label="Permalink to &quot;What every variant has in common&quot;">​</a></h2><p>Three guarantees, regardless of variant:</p><ol><li><strong>Readable construction.</strong> Named, fluent setters at the call site instead of positional <code>new</code> arguments.</li><li><strong>Immutability of the product.</strong> Fields are <code>final</code>; no setters on the product itself.</li><li><strong>Construction is funneled</strong> through a chokepoint (<code>build()</code>). Validation, when it exists, runs there — never observed in a half-built state.</li></ol><p>The variants differ in <em>how strictly</em> each of these is enforced and <em>what additional structure</em> the pattern offers (recipe reuse, multi-product polymorphism). They do not differ on the underlying philosophy.</p><h2 id="what-you-should-not-use-builder-for" tabindex="-1">What you should not use Builder for <a class="header-anchor" href="#what-you-should-not-use-builder-for" aria-label="Permalink to &quot;What you should not use Builder for&quot;">​</a></h2><ul><li>An object with 2–3 always-required fields and no validation. A plain constructor is enough.</li><li>A mutable domain entity that changes over time. JavaBeans-style setters are correct there.</li><li>Selecting <em>which subclass to construct</em>. That&#39;s Factory Method, not Builder. Builder configures one product; Factory chooses among products.</li></ul><h2 id="cross-references" tabindex="-1">Cross-references <a class="header-anchor" href="#cross-references" aria-label="Permalink to &quot;Cross-references&quot;">​</a></h2><ul><li><code>creational/CreationalPatternsRoadmap.md</code> — learning sequence.</li><li><code>creational/Factory.md</code> — the same overview shape applied to the factory family.</li><li><code>todo/AccessModifiersDeepDive.md</code> — section &quot;Class-level modifier decisions&quot; covers <code>final class</code>, <code>static class</code>, and the private-constructor chokepoint pattern that all Builder variants rely on.</li><li><code>todo/FoundationsToRead.md</code> — LSP entry covers why <code>OfferLetter extends JobOffer</code> would be wrong, an insight that shaped <code>BuilderDirectorGof.md</code>.</li></ul>',15)])])}const f=t(i,[["render",d]]);export{m as __pageData,f as default};
